class Solution
{
public:
    void wallsAndGates(vector< vector< int >>& rooms)
    {
        int m = rooms.size();
        if (!m)
        {
            return;
        }
        int n = rooms[0].size();
        queue< pair< int, int >>q;
        for (int i = 0; i < m;++i) for(int j = 0; j < n;++j) if(rooms[i][j] == 0) q.push( { i, j });
        int dr[4] = { 1, - 1, 0, 0 }, dc[4] = { 0, 0, 1, - 1 };
        while (!q.empty())
        {
            auto p = q.front();
            q.pop();
            for (int z = 0; z < 4;++z)
            {
                int r = p.first + dr[z], c = p.second + dc[z];
                if (r < 0 || r >= m || c < 0 || c >= n || rooms[r][c] != INT_MAX)
                {
                    continue;
                }
                rooms[r][c] = rooms[p.first][p.second] + 1;
                q.push( { r, c });
            }
        }
    }
};
